def page(id,title,msg,chapter,mode,nodes=(),rows=None,headers=None,refs=('design',),note='현장·계약·실증 결과 확인 전 협의용 제안',stage='business',intent=None):
 ns=[dict(id=f'n{i+1}',label=n[0],detail=n[1],icon=n[2] if len(n)>2 else 'document') for i,n in enumerate(nodes)]
 kind='contact-card' if mode=='contact' else 'existing'; intent=intent or ('comparative' if rows else 'structural')
 marks=['comparison'] if rows else ['connectors']
 if mode in ['cover','scene']:marks=['scene','brand'] if mode=='cover' else ['scene']
 if mode=='contact':marks=['brand']
 if mode=='states':marks=['screen','comparison']
 if mode=='schedule':marks=['timeline'];intent='temporal'
 if mode=='budget':marks=['chart'];intent='quantitative'
 v=dict(kind=kind,intent=intent,takeaway=msg,encoding='safesurface:'+mode+'; '+('행별로 조건과 조치·증거를 대응하여 비교' if rows else '명시한 순서·경계와 연결 관계를 읽는 편집 가능 도식'),evidenceIds=list(refs),nodes=ns or [dict(id='n1',label=title,detail=msg,icon='document')],edges=[dict(from_=ns[i]['id'],to=ns[i+1]['id'],label='') for i in range(len(ns)-1)],legend=note,readingGuide=dict(message=msg,keyPhrase=' '.join(msg.split(' ')[:2]),focusPhrases=[n['label'] for n in ns[:4]] or ['확인 전'],tone='amber' if mode in ['fallback','states'] else 'teal'),explanation=dict(readerTask=title+'의 판단 기준을 이해',howToRead='상단 핵심 문장을 확인한 뒤 '+('같은 행의 조건·조치·근거를 좌우로 비교한다' if rows else '표시된 경계와 순서를 따라 입력·행동·검증의 관계를 읽는다'),notProven=note,requiredMarks=marks))
 for e in v['edges']:e['from']=e.pop('from_')
 sec=dict(id=id,chapter=chapter,visual='matrix' if rows else 'editorial',kicker='SLT SafeSurface AI',items=[dict(label=n['label'],detail=n['detail']) for n in ns[:4]],caption=note,candidateIds=[])
 if not sec['items']:sec['items']=[dict(label='협의 범위',detail=msg)]
 if rows: sec.update(headers=headers,rows=rows)
 beat=dict(id=id,sectionId=id,stage=stage,title=title,question=title+'에서 무엇을 확인해야 하는가?',answer=msg,proofClaimIds=list(refs),visualPurpose=title+'의 핵심 관계를 한눈에 설명한다.',limitation=note,visualPlan=v)
 pages.append((sec,beat));return v
